<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Hash,RateLimiter,Storage};
use Illuminate\Support\Str;
use App\Domain\TripService;
class RideController extends Controller {
 public function __construct(private TripService $trips){}
 private function account(Request $r, array $roles=[]): object {
  $a=DB::table('accounts')->find($r->session()->get('account_id'));abort_unless($a,401,'Please verify your phone number.');abort_if($roles && !in_array($a->role,$roles),403,'Your role cannot perform this action.');return $a;
 }
 private function dev(): void {abort_if(app()->environment('production') || !config('ride.development_adapters'),503,'Development adapters are disabled.');}
 private function limited(string $key,int $max,int $seconds): void {abort_if(RateLimiter::tooManyAttempts($key,$max),429,'Too many attempts. Please try later.');RateLimiter::hit($key,$seconds);}
 private function driver(object $a): object {$d=DB::table('drivers')->where('account_id',$a->id)->first();abort_unless($d,403,'Driver application required.');return $d;}
 private function access(object $a,object $t): void { $d=$t->driver_id?DB::table('drivers')->find($t->driver_id):null;abort_unless($a->id===$t->rider_id || ($d && $d->account_id===$a->id) || in_array($a->role,['admin','ops']),403,'This trip belongs to another account.'); }
 private function audit(object $a,string $action,string $resource,string $reason,array $details=[]): void {DB::table('audit_records')->insert(['actor_id'=>$a->id,'action'=>$action,'resource'=>$resource,'reason'=>$reason,'details'=>json_encode($details)]);}
 public function bootstrap(Request $r): array {
  $a=DB::table('accounts')->find($r->session()->get('account_id'));$s=DB::table('service_settings')->first();
  return ['csrf_token'=>csrf_token(),'account'=>$a?['id'=>$a->id,'first_name'=>$a->first_name,'role'=>$a->role]:null,'landmarks'=>DB::table('landmarks')->orderBy('id')->get()->map(fn($l)=>['id'=>$l->id,'name'=>$l->name,'aliases'=>json_decode($l->aliases,true),'latitude'=>(float)$l->latitude,'longitude'=>(float)$l->longitude,'verified'=>$l->verified,'meeting_point'=>$l->meeting_point]),'service'=>['name'=>$s?->name,'opens'=>$s?->opens,'closes'=>$s?->closes,'timezone'=>$s?->timezone,'enabled'=>$s?->enabled],'development'=>(bool)config('ride.development_adapters') && !app()->environment('production'),'support_hours'=>config('ride.support_hours')];
 }
 public function otp(Request $r): array {
  $v=$r->validate(['phone'=>['required','regex:/^\+265[0-9]{9}$/']]);$this->limited('otp-phone:'.hash('sha256',$v['phone']),3,600);$this->limited('otp-ip:'.$r->ip(),10,600);$this->dev();
  $id=(string)Str::uuid();$code=(string)random_int(100000,999999);DB::table('otp_challenges')->insert(['id'=>$id,'phone'=>$v['phone'],'code_hash'=>Hash::make($code),'expires_at'=>now()->addMinutes(5)]);
  return ['challenge_id'=>$id,'development_code'=>$code,'message'=>'Development verification only. No SMS was sent.'];
 }
 public function verify(Request $r): array {
  $this->dev();$this->limited('verify:'.$r->ip(),30,600);$v=$r->validate(['challenge_id'=>'required|uuid','code'=>'required|digits:6','first_name'=>'required|string|max:60']);
  $result=DB::transaction(function()use($v){$c=DB::table('otp_challenges')->where('id',$v['challenge_id'])->lockForUpdate()->first();abort_unless($c && !$c->consumed_at && now()->lt($c->expires_at),422,'Verification expired. Request another code.');abort_if($c->attempts>=5,429,'Too many verification attempts.');
   DB::table('otp_challenges')->where('id',$c->id)->increment('attempts');if(!Hash::check($v['code'],$c->code_hash))return null;
   DB::table('otp_challenges')->where('id',$c->id)->update(['consumed_at'=>now()]);$a=DB::table('accounts')->where('phone',$c->phone)->first();
   if(!$a){$id=DB::table('accounts')->insertGetId(['phone'=>$c->phone,'first_name'=>$v['first_name'],'role'=>'rider','created_at'=>now(),'updated_at'=>now()]);$a=DB::table('accounts')->find($id);}return $a;
  },5);abort_unless($result,422,'Verification code is incorrect.');$r->session()->regenerate();$r->session()->put('account_id',$result->id);return ['account'=>['id'=>$result->id,'first_name'=>$result->first_name,'role'=>$result->role]];
 }
 public function demoLogin(Request $r): array {
  $this->dev();$this->limited('demo-login:'.$r->ip(),20,60);$v=$r->validate(['role'=>'required|in:admin,driver,rider']);$phone=['admin'=>'+265990000001','driver'=>'+265990000002','rider'=>'+265990000003'][$v['role']];$a=DB::table('accounts')->where('phone',$phone)->first();abort_unless($a,503,'Run the demo seeder first.');$r->session()->regenerate();$r->session()->put('account_id',$a->id);return ['role'=>$a->role];
 }
 public function logout(Request $r): array {$r->session()->invalidate();$r->session()->regenerateToken();return ['ok'=>true];}
 private function point(array $p): array {
  if(isset($p['landmark_id'])){$l=DB::table('landmarks')->find($p['landmark_id']);abort_unless($l,422,'Landmark not found.');return ['landmark_id'=>$l->id,'display_name'=>$l->name,'latitude'=>(float)$l->latitude,'longitude'=>(float)$l->longitude,'verified'=>$l->verified,'meeting_point'=>$l->meeting_point];}
  return ['display_name'=>$p['display_name'],'latitude'=>(float)$p['latitude'],'longitude'=>(float)$p['longitude'],'meeting_point'=>$p['meeting_point']??null];
 }
 public function quote(Request $r): array {
  $this->limited('quote:'.$r->ip(),60,60);$rules=[];foreach(['pickup','destination'] as $p){$rules[$p]='required|array';$rules["$p.landmark_id"]='nullable|integer';$rules["$p.display_name"]="required_without:$p.landmark_id|string|max:120";$rules["$p.latitude"]="required_without:$p.landmark_id|numeric|between:-90,90";$rules["$p.longitude"]="required_without:$p.landmark_id|numeric|between:-180,180";$rules["$p.meeting_point"]='nullable|string|max:200';}$v=$r->validate($rules);return $this->trips->quote($this->point($v['pickup']),$this->point($v['destination']));
 }
 public function requestTrip(Request $r): array {
  $a=$this->account($r,['rider']);$this->limited('booking:'.$a->id,20,60);$v=$r->validate(['quote_id'=>'required|uuid','pickup_note'=>'nullable|string|max:500','payment_method'=>'required|in:cash']);$key=$r->header('Idempotency-Key');abort_unless($key && preg_match('/^[a-zA-Z0-9-]{8,100}$/',$key),422,'A valid Idempotency-Key header is required.');$t=$this->trips->request($a->id,$v['quote_id'],$key,$v['pickup_note']??'');return $this->trips->view($t,$a->id,$a->role);
 }
 public function trips(Request $r): array {
  $a=$this->account($r);$this->trips->expire();$q=DB::table('trips')->orderByDesc('created_at');if($a->role==='rider')$q->where('rider_id',$a->id);elseif($a->role==='driver')$q->where('driver_id',$this->driver($a)->id);elseif(!in_array($a->role,['admin','ops']))abort(403);
  return ['trips'=>$q->limit(100)->get()->map(fn($t)=>$this->trips->view($t,$a->id,$a->role))];
 }
 public function trip(Request $r,string $id): array {$a=$this->account($r);$this->trips->expire();$t=DB::table('trips')->find($id);abort_unless($t,404);$this->access($a,$t);return $this->trips->view($t,$a->id,$a->role);}
 public function action(Request $r,string $id,string $action): array {$a=$this->account($r);$this->limited('action:'.$a->id,60,60);$v=$r->validate(['pin'=>'nullable|digits:4','reason'=>'nullable|string|max:1000']);$t=$this->trips->transition($id,$a->id,$a->role,$action,$v['pin']??null,$v['reason']??null);return $this->trips->view($t,$a->id,$a->role);}
 public function driverHome(Request $r): array {
  $a=$this->account($r,['driver']);$d=$this->driver($a);$this->trips->expire();
  $q=DB::table('trips')->where('state','matching')->where('expires_at','>',now())->whereNotIn('id',DB::table('offer_declines')->where('driver_id',$d->id)->select('trip_id'));
  $offers=$d->online && $d->status==='approved' && $d->vehicle_approved ? $q->limit(20)->get()->map(fn($t)=>$this->trips->view($t,$a->id,$a->role)):[];
  $completed=DB::table('trips')->where('driver_id',$d->id)->where('state','completed')->whereDate('completed_at',now('Africa/Blantyre')->toDateString())->get();
  return ['driver'=>['id'=>$d->id,'status'=>$d->status,'online'=>$d->online,'vehicle'=>$d->vehicle,'plate'=>$d->plate,'vehicle_approved'=>$d->vehicle_approved],'available_credit_minor'=>$this->trips->balance($d->id),'today_earnings_minor'=>$completed->sum(fn($t)=>json_decode($t->pricing,true)['driver_minor']),'completed_trips'=>$completed->count(),'offers'=>$offers,'ledger'=>DB::table('credit_ledger')->where('driver_id',$d->id)->orderByDesc('id')->limit(100)->get(),'review_cases'=>DB::table('incidents')->where('account_id',$a->id)->get()];
 }
 public function online(Request $r): array {
  $a=$this->account($r,['driver']);$v=$r->validate(['online'=>'required|boolean']);DB::transaction(function()use($a,$v){$d=DB::table('drivers')->where('account_id',$a->id)->lockForUpdate()->first();abort_unless($d,403);if($v['online'])abort_unless($d->status==='approved' && $d->vehicle_approved,403,'Your driver and vehicle approvals are required.');DB::table('drivers')->where('id',$d->id)->update(['online'=>$v['online'],'updated_at'=>now()]);},5);return $this->driverHome($r);
 }
 public function accept(Request $r,string $id): array {$a=$this->account($r,['driver']);$t=$this->trips->accept($this->driver($a)->id,$id,$a->id);return $this->trips->view($t,$a->id,$a->role);}
 public function decline(Request $r,string $id): array {$a=$this->account($r,['driver']);DB::table('offer_declines')->insertOrIgnore(['driver_id'=>$this->driver($a)->id,'trip_id'=>$id]);return ['ok'=>true];}
 public function application(Request $r): array {
  $a=$this->account($r,['rider','driver']);$v=$r->validate(['vehicle'=>'required|string|max:100','plate'=>'required|string|max:30','details'=>'nullable|string|max:2000']);
  DB::transaction(function()use($a,$v){$d=DB::table('drivers')->where('account_id',$a->id)->lockForUpdate()->first();abort_if($d && $d->status==='approved',409,'Contact support to change an approved vehicle.');DB::table('drivers')->updateOrInsert(['account_id'=>$a->id],['vehicle'=>$v['vehicle'],'plate'=>$v['plate'],'application'=>json_encode(['details'=>$v['details']??'']),'status'=>'pending','vehicle_approved'=>false,'online'=>false,'created_at'=>now(),'updated_at'=>now()]);DB::table('accounts')->where('id',$a->id)->update(['role'=>'driver']);},5);return ['status'=>'pending','message'=>'Progress saved. Human review is required.'];
 }
 public function upload(Request $r): array {$a=$this->account($r,['driver']);$d=$this->driver($a);abort_if($d->status==='approved',409,'Contact support to replace approved documents.');$r->validate(['document'=>'required|file|mimes:pdf,jpg,jpeg,png|max:5120']);$path=$r->file('document')->store('driver-documents','local');DB::table('drivers')->where('id',$d->id)->update(['document_path'=>$path]);return ['uploaded'=>true];}
 public function incident(Request $r): array {$a=$this->account($r);$v=$r->validate(['trip_id'=>'nullable|uuid','category'=>'required|in:help,already_in_car,road_report,fee_dispute','description'=>'required|string|max:2000']);if(!empty($v['trip_id'])){$t=DB::table('trips')->find($v['trip_id']);abort_unless($t,404);$this->access($a,$t);}$id=DB::table('incidents')->insertGetId(['account_id'=>$a->id,'trip_id'=>$v['trip_id']??null,'category'=>$v['category'],'description'=>$v['description'],'status'=>'open','review_due_at'=>now()->addHours(48),'created_at'=>now(),'updated_at'=>now()]);return ['id'=>$id,'status'=>'open','review_due_at'=>now()->addHours(48)->toIso8601String()];}
 public function admin(Request $r): array {
  $a=$this->account($r,['admin','ops','reviewer']);$result=['drivers'=>DB::table('drivers')->join('accounts','accounts.id','=','drivers.account_id')->select('drivers.id','drivers.status','drivers.vehicle','drivers.plate','drivers.vehicle_approved','drivers.document_path','accounts.first_name')->get(),'settings'=>DB::table('service_settings')->first(),'pricing'=>DB::table('pricing_rules')->orderByDesc('id')->get()];
  if(in_array($a->role,['admin','ops']))$result+=['ledger'=>DB::table('credit_ledger')->orderByDesc('id')->limit(200)->get(),'events'=>DB::table('trip_events')->orderByDesc('id')->limit(200)->get(),'incidents'=>DB::table('incidents')->orderByDesc('id')->limit(100)->get(),'audit'=>DB::table('audit_records')->orderByDesc('id')->limit(100)->get()];return $result;
 }
 public function review(Request $r,int $id): array {
  $a=$this->account($r,['admin','reviewer']);$v=$r->validate(['status'=>'required|in:approved,rejected,suspended','vehicle_approved'=>'required|boolean','reason'=>'required|string|min:5|max:1000']);DB::transaction(function()use($a,$v,$id){$d=DB::table('drivers')->where('id',$id)->lockForUpdate()->first();abort_unless($d,404);abort_if($v['status']==='approved' && !$d->document_path,422,'Driver documents must be reviewed first.');DB::table('drivers')->where('id',$id)->update(['status'=>$v['status'],'vehicle_approved'=>$v['vehicle_approved'],'online'=>false,'updated_at'=>now()]);$this->audit($a,'driver_review',(string)$id,$v['reason'],['status'=>$v['status'],'vehicle_approved'=>$v['vehicle_approved']]);},5);return ['ok'=>true];
 }
 public function document(Request $r,int $id) {$a=$this->account($r,['admin','reviewer','driver']);$d=DB::table('drivers')->find($id);abort_unless($d,404);abort_unless(in_array($a->role,['admin','reviewer']) || $d->account_id===$a->id,403);abort_unless($d->document_path && Storage::disk('local')->exists($d->document_path),404);return Storage::disk('local')->download($d->document_path,'driver-document', ['Cache-Control'=>'private, no-store','X-Content-Type-Options'=>'nosniff']);}
 public function pricing(Request $r): array {$a=$this->account($r,['admin']);$v=$r->validate(['base_minor'=>'required|integer|min:0|max:100000000','per_km_minor'=>'required|integer|min:0|max:10000000','commission_bps'=>'required|integer|between:0,10000','reason'=>'required|string|min:5|max:1000']);$id=DB::transaction(function()use($a,$v){$id=DB::table('pricing_rules')->insertGetId(['base_minor'=>$v['base_minor'],'per_km_minor'=>$v['per_km_minor'],'commission_bps'=>$v['commission_bps'],'created_at'=>now(),'updated_at'=>now()]);$this->audit($a,'pricing_version',(string)$id,$v['reason']);return $id;},5);return ['version'=>$id];}
 public function settings(Request $r): array {$a=$this->account($r,['admin']);$v=$r->validate(['name'=>'required|string|max:120','opens'=>'required|date_format:H:i','closes'=>'required|date_format:H:i','enabled'=>'required|boolean','bounds.south'=>'required|numeric|between:-90,90','bounds.north'=>'required|numeric|between:-90,90|gt:bounds.south','bounds.west'=>'required|numeric|between:-180,180','bounds.east'=>'required|numeric|between:-180,180|gt:bounds.west','reason'=>'required|string|min:5|max:1000']);DB::transaction(function()use($a,$v){DB::table('service_settings')->where('id',1)->update(['name'=>$v['name'],'opens'=>$v['opens'],'closes'=>$v['closes'],'enabled'=>$v['enabled'],'bounds'=>json_encode($v['bounds']),'updated_at'=>now()]);$this->audit($a,'service_settings','1',$v['reason'],$v);},5);return ['ok'=>true];}
 public function landmark(Request $r): array {$a=$this->account($r,['admin','ops']);$v=$r->validate(['id'=>'nullable|integer|exists:landmarks,id','name'=>'required|string|max:120','aliases'=>'required|array','aliases.*'=>'string|max:120','latitude'=>'required|numeric|between:-90,90','longitude'=>'required|numeric|between:-180,180','verified'=>'required|boolean','meeting_point'=>'nullable|string|max:200','reason'=>'required|string|min:5|max:1000']);DB::transaction(function()use($a,$v){$data=['name'=>$v['name'],'aliases'=>json_encode($v['aliases']),'latitude'=>$v['latitude'],'longitude'=>$v['longitude'],'verified'=>$v['verified'],'meeting_point'=>$v['meeting_point']??null,'updated_at'=>now()];if(isset($v['id'])){DB::table('landmarks')->where('id',$v['id'])->update($data);$id=$v['id'];}else{$id=DB::table('landmarks')->insertGetId($data+['created_at'=>now()]);}$this->audit($a,'landmark',(string)$id,$v['reason']);},5);return ['ok'=>true];}
 public function adjustment(Request $r,int $id): array {$a=$this->account($r,['admin']);$v=$r->validate(['amount_minor'=>'required|integer|not_in:0|between:-100000000,100000000','reference'=>'required|string|min:8|max:100','reason'=>'required|string|min:5|max:1000']);DB::transaction(function()use($a,$v,$id){abort_unless(DB::table('drivers')->where('id',$id)->lockForUpdate()->first(),404);$ref='manual:'.$v['reference'];$prior=DB::table('credit_ledger')->where('reference',$ref)->first();if($prior){abort_unless($prior->driver_id===$id && $prior->amount_minor===$v['amount_minor'],409,'Reference already used.');return;}abort_if($this->trips->balance($id)+$v['amount_minor']<0,422,'Adjustment would make available credit negative.');$this->trips->ledger($id,null,$ref,'adjustment',$v['amount_minor'],$v['reason'],$a->id);$this->audit($a,'credit_adjustment',(string)$id,$v['reason'],['reference'=>$ref,'amount_minor'=>$v['amount_minor']]);},5);return ['available_credit_minor'=>$this->trips->balance($id)];}
 public function resolve(Request $r,int $id): array {$a=$this->account($r,['admin','ops']);$v=$r->validate(['reason'=>'required|string|min:5|max:2000']);DB::transaction(function()use($a,$v,$id){abort_unless(DB::table('incidents')->where('id',$id)->lockForUpdate()->first(),404);DB::table('incidents')->where('id',$id)->update(['status'=>'resolved','updated_at'=>now()]);$this->audit($a,'incident_resolution',(string)$id,$v['reason']);},5);return ['ok'=>true];}
}